insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('comprovantes','comprovantes',false,5242880,array['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types; drop policy if exists pagamentos_self_read on public.pagamentos; create policy pagamentos_self_read on public.pagamentos for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.jogadores j where j.id=pagamentos.jogador_id and j.user_id=auth.uid()) or public.is_admin()); create or replace function public.meus_pagamentos() returns setof public.pagamentos language sql stable security definer set search_path='' as $$ select p.* from public.pagamentos p where p.user_id=auth.uid() or exists(select 1 from public.jogadores j where j.id=p.jogador_id and j.user_id=auth.uid()) order by p.created_at desc $$; create or replace function public.enviar_comprovante(p_pagamento_id uuid,p_path text) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or split_part(p_path,'/',1)<>auth.uid()::text then raise exception 'Acesso negado'; end if; update public.pagamentos p set comprovante_path=p_path,comprovante_enviado_em=now(),updated_at=now() where p.id=p_pagamento_id and p.status in ('pendente','atrasado') and (p.user_id=auth.uid() or exists(select 1 from public.jogadores j where j.id=p.jogador_id and j.user_id=auth.uid())); if not found then raise exception 'Cobrança indisponível'; end if; end $$; create or replace function public.notificar_admin_comprovante() returns trigger language plpgsql security definer set search_path='' as $$ declare v_nome text; begin if new.comprovante_path is null or new.comprovante_path is not distinct from old.comprovante_path then return new; end if; select coalesce((select coalesce(nullif(j.apelido,''),j.nome) from public.jogadores j where j.id=new.jogador_id),(select coalesce(nullif(p.apelido,''),p.nome) from public.profiles p where p.id=new.user_id),'Jogador') into v_nome; insert into public.notificacoes(user_id,titulo,mensagem,link,tipo,referencia_id,criada_por) select id,'Novo comprovante',v_nome||' enviou um comprovante para validação.','/admin','comprovante',new.id,auth.uid() from public.profiles where role in ('admin','superadmin') and ativo and id<>auth.uid() on conflict (user_id,tipo,referencia_id) where referencia_id is not null do update set titulo=excluded.titulo,mensagem=excluded.mensagem,link=excluded.link,criada_por=excluded.criada_por,entregue_em=null,lida_em=null,created_at=now(); return new; end $$; drop trigger if exists pagamentos_notificar_comprovante on public.pagamentos; create trigger pagamentos_notificar_comprovante after update of comprovante_path on public.pagamentos for each row execute function public.notificar_admin_comprovante(); revoke all on function public.meus_pagamentos(),public.enviar_comprovante(uuid,text) from public; grant execute on function public.meus_pagamentos(),public.enviar_comprovante(uuid,text) to authenticated;
